.venv/bin/python3 -c "import requests
print('Downloading PWT 11.0...')
try:
    r = requests.get('https://www.rug.nl/ggdc/docs/pwt110.xlsx')
    if r.status_code == 200:
        open('pwt.xlsx', 'wb').write(r.content)
        print('PWT 11.0 Downloaded.')
    else:
        print(f'PWT 11.0 Failed: {r.status_code}')
except Exception as e:
    print(f'PWT Error: {e}')

print('Downloading WEO...')
try:
    r = requests.get('https://www.imf.org/-/media/files/publications/weo/weo-database/2024/october/weooct2024all.xls')
    if r.status_code == 200:
        open('weo.xls', 'wb').write(r.content) # Note .xls
        print('WEO Downloaded.')
    else:
        print(f'WEO Failed: {r.status_code}')
except Exception as e:
    print(f'WEO Error: {e}')
"

